 PermissionProtocol.GrantRow grant(PermissionProtocol.Scope scope,String action,String purpose)throws Exception{String key=actor+scope+action+purpose;var prior=grants.values().stream().filter(g->(g.subjectId()+new PermissionProtocol.Scope(tenant,g.projectId(),g.resourceKind(),g.resourceId())+g.action()+purpose).equals(key)).findFirst();if(prior.isPresent())return prior.get();var c=new PermissionProtocol.Condition("1.0.0",List.of("local"),List.of(purpose),new PermissionProtocol.Delegation(List.of(),List.of(),List.of(),null,null));var g=new PermissionProtocol.GrantRow(UUID.randomUUID().toString(),actor,scope.project_id(),scope.resource_kind(),scope.resource_id(),action,json.canonicalObject(c),"ACTIVE",now.minusDays(1),now.plusDays(1),id(9),"1.0.0",json.manifestSha256(),BigInteger.ONE);grants.put(g.grantId(),g);return g;}
 <T>T tx(Callable<T> c)throws Exception{TransactionSynchronizationManager.setActualTransactionActive(true);try(var scope=TenantScope.open(new TenantScope.Identity(tenant,actor,BigInteger.ONE,BigInteger.ONE,BigInteger.ONE))){scope.verifyTransaction(new TenantWatermarks(BigInteger.ONE,BigInteger.ONE));try{return c.call();}finally{scope.finishTransaction();}}finally{TransactionSynchronizationManager.setActualTransactionActive(false);}}
 byte[] body()throws Exception{return schema.canonical(new Author("1.0.0",new AgentExecutionPolicySchemaTest().input(),"Real service fixture")).getBytes(java.nio.charset.StandardCharsets.UTF_8);}
 JsonNode author()throws Exception{return tx(()->service.author(a,"author-original-key",body()));}
 JsonNode decide(String decision,String key)throws Exception{var r=new Decide("1.0.0",state.revision().toString(),new PermissionProtocol.Basis(row.versionId(),row.definitionHash()),decision,"Independent decision fixture");return tx(()->service.decide(a,key,schema.canonical(r).getBytes(java.nio.charset.StandardCharsets.UTF_8)));}
 @Test void authorIndependentApprovalAndTypedReadUseRealJournal()throws Exception{var receipt=author();assertEquals("DRAFT",state.status());actor=id(102);now=now.plusMinutes(1);var approved=decide("APPROVE","approve-original-key");assertEquals("APPROVED",state.status());assertEquals(2,records.size());assertEquals(2,audits.size());assertEquals(2,events.size());assertEquals("APPROVED",tx(()->service.read(a,row.versionId())).path("status").asText());assertEquals(approved,tx(()->service.receipt(a,row.versionId(),approved.path("resource_id").asText(),approved.path("operation_id").asText())));}
